from topics import TOPICS,T,C,V,table,process

def lab(slug,semester,number,title,question,intro,contents,quiz,case,reading):
    T(slug,semester,f'Лабораторная работа № {number}. {title}',question,intro,contents,quiz,case,reading)
    TOPICS[-1]['category']='laboratory'

lab('lab-system-map',5,1,'Составление схемы состава информационной системы предприятия',
'Как получить проверяемую схему из исходного описания?',
'Результат работы — схема состава и связей, таблица пяти видов обеспечения и обозначенная граница. Используйте условные сведения предприятия, приведённые на следующих экранах.',[
C('Исходные данные предприятия','Склад «Вектор»: 8 АРМ кладовщиков, 2 АРМ закупщиков, 1 АРМ администратора; 4 сканера; 2 принтера этикеток; 1 коммутатор; 1 сервер приложения и СУБД; 1 отдельное хранилище копий. Внешний поставщик передаёт накладные через файл.',
'Все числа относятся к учебному предприятию. Различайте количество устройств и их роли. Приложение и СУБД находятся на одном сервере, поэтому это две программные роли на одном физическом узле. Хранилище копий является отдельным компонентом, но само его наличие не доказывает возможность восстановления. Для внешнего поставщика показываем границу и формат обмена; его внутренние устройства в схему не включаем.'),
C('Порядок построения','1. Выпишите назначение и границу. 2. Сгруппируйте АРМ по роли. 3. Соедините сеть, сервер и периферию; подпишите данные и назначения линий. 4. Отдельно покажите копии. 5. Добавьте таблицу обеспечения и проверку функции.',
'Сначала выполняется самостоятельное построение. Группа АРМ на схеме допускается, если подписано число и ясно, где подключается периферия. Не рисуйте все виды обеспечения одинаковыми устройствами: организационное обеспечение показывается ролями и порядком действий, правовое — основаниями и документами. Контрольная функция — приёмка накладной с сохранением движения и возможностью восстановить учебные данные. Стрелка к копии должна объяснять, что копируется и откуда.'),
C('Что сдавать','Схема с легендой и границей; перечень компонентов с количеством; таблица пяти видов обеспечения; маршрут приёмки одной накладной; перечень зависимостей и одной общей точки отказа.',
'Сопоставьте каждый компонент исходных данных со схемой или таблицей. Затем другой участник должен проследить путь накладной и назвать, какие компоненты нужны для записи. Отдельно отметьте, что единственный коммутатор и единственный сервер остаются обязательными точками. Нельзя считать работу завершённой только по наличию красивых значков. Все исходные объекты должны быть найдены в результате.',
'Схема проверяется по полноте исходных объектов и воспроизводимому маршруту функции.')],
dict(prompt='Сколько АРМ указано в исходных данных?',options=['8','10','11','17'],correct=2,explanation='8 кладовщиков + 2 закупщика + 1 администратора = 11 АРМ. Сканеры и принтеры считаются отдельно.'),
dict(task='Определите число АРМ, не прибавляя периферийные устройства.',output='Введите число.',variants=[
V('Исходный состав','8 АРМ кладовщиков, 2 закупщиков, 1 администратора; 4 сканера.',[('Кладовщики','8'),('Остальные АРМ','2 + 1 = 3'),('Всего АРМ','8 + 3 = 11')],'11','Сканеры — периферия, не дополнительные рабочие места. Всего 11 АРМ.',['11']),
V('Расширение','К исходным 11 АРМ добавлены 3 АРМ второй смены; принтер заменён, число АРМ от замены не изменилось.',[('Было','11'),('Добавлено','3'),('Всего','14')],'14','11+3=14 АРМ; замена периферии не изменяет этот счёт. Проверьте порты и права новых рабочих мест.',['14'])]),'systems')

lab('lab-compare',5,2,'Сравнительный анализ информационных систем одного назначения',
'Как отделить обязательное условие от предпочтения?',
'Сравните две условные системы снабжения. Результат — аргументированный выбор по общим критериям и указание данных, которые ещё необходимо проверить.',[
C('Условные кандидаты и критерии','Обе системы поддерживают закупку и склад. A: автономность нет; выгрузка есть; стоимость 30; удобство 4/5. B: автономность есть; выгрузка есть; стоимость 50; удобство 3/5. Стоимость дана в условных единицах. Обязательна работа при разрыве канала.',
'Сначала составьте одинаковый набор признаков. Данные кандидатов являются учебными, это не оценка реальных продуктов. Требование автономности является фильтром, а стоимость и удобство — предпочтениями среди прошедших фильтр. Если продукт не выполняет обязательную функцию, высокая оценка удобства не компенсирует нарушение.'),
C('Порядок анализа','Проверьте обязательные функции и ограничения. Исключите неподходящие варианты. Для оставшихся сравните стоимость, выгрузку, сопровождение и удобство на одном сценарии: поступление 10 единиц товара и проверка остатка.',
'Не заменяйте неизвестное положительным баллом. Если автономность заявлена, предложите проверку: разорвать канал на разрешённом стенде, оформить документ, восстановить связь и сверить результат. Отдельно проверьте, какой набор данных доступен без сети. Одно и то же слово «выгрузка» может означать отчёт PDF или полные данные, пригодные для переноса; условия должны раскрывать нужный вид.'),
C('Отчёт и изменённый случай','Сдайте матрицу критериев с источником каждого значения, решение и план проверки двух спорных характеристик. Затем пересмотрите выбор, если автономность перестала быть обязательной, а единственным критерием стала минимальная стоимость.',
'Ответ должен меняться вместе с условиями. В исходном случае A исключён, поэтому выбирается B из представленных вариантов. В изменённом случае оба выполняют обязательные условия, и по стоимости выбирается A. Этот разбор не создаёт универсальной рекомендации; он показывает прозрачную зависимость решения от критериев.')],
dict(prompt='Может ли удобство 5/5 компенсировать отсутствие обязательной функции?',options=['Да, всегда','Нет, сначала применяется обязательный фильтр','Да, если сайт красивый','Только при большом числе пользователей'],correct=1,explanation='Обязательное условие определяет допустимость. Предпочтения сравнивают уже допустимые варианты.'),
dict(task='Выберите A или B по условиям текущего случая.',output='Введите букву.',variants=[
V('Автономность обязательна','A=30, без автономности; B=50, с автономностью. Остальные обязательные функции равны.',[('Фильтр','Автономность требуется'),('A','Исключён'),('B','Допустим')],'B','Только B выполняет обязательное условие. Нужна проверка автономного сценария на стенде.',['b']),
V('Автономность не требуется','Оба выполняют обязательные функции; единственный критерий — меньшая стоимость. A=30, B=50.',[('Фильтр','Оба допустимы'),('Критерий','Стоимость'),('Сравнение','30 < 50')],'A','По изменённому условию выбирается A; прежнее решение не переносится автоматически.',['a'])]),'systems')

lab('lab-display',5,3,'Обслуживание системы отображения информации',
'Как локализовать отсутствие изображения без случайной смены всех настроек?',
'Работайте с разрешённым дисплеем и источником либо с описанным учебным случаем. Физическое подключение и настройку отмечайте как выполненные только при реальной проверке оборудования.',[
C('Стенд и симптомы','Стенд: ноутбук HDMI OUT → проверенный HDMI-кабель → дисплей HDMI IN 1. Исходный режим 1920×1080, 60 Гц, только если он поддерживается обоими устройствами. Симптом: «Нет сигнала». Настройки и исходный тракт зафиксируйте до изменения.',
'Не отключайте незнакомые устройства и питание работающих систем. Для учебной проверки используйте один источник и один дисплей, доступ к которым разрешён. Открывающееся меню дисплея подтверждает питание и локальную индикацию, но не входной видеосигнал. Если у конкретного оборудования другой поддерживаемый режим, берите его из документации, не навязывайте параметры примера.'),
C('Порядок проверки и настройки','Проверьте питание и локальное меню; выбранный вход; включение видеовыхода источника; поддерживаемый режим; разъёмы и кабель. Меняйте один фактор. После восстановления проверьте тестовую картинку, читаемость и устойчивость.',
'В Windows 11 режим внешнего дисплея выбирается через Win+P или параметры дисплея. Укажите реальное действие и наблюдение. Если выбран IN 2, а кабель стоит в IN 1, сначала исправляется выбор входа. Если вход верен, используйте проверенный короткий кабель и известный поддерживаемый режим. Не подтверждайте исправность кабеля только осмотром оболочки.'),
C('Два контрольных случая','A: меню дисплея доступно, выбран IN 2, кабель в IN 1; после выбора IN 1 появляется картинка. B: вход верен, с тем же источником проверенный короткий кабель работает, исходный — нет.',
'В A причина локализована в выбранном входе, в B — в исходном кабельном тракте при заданных неизменных условиях. Если изменены одновременно вход, кабель и разрешение, отдельную причину установить нельзя. После устранения верните штатное размещение и подтвердите, что итоговая конфигурация действительно работает; успешный короткий тест вне штатного тракта его не проверяет.'),
C('Отчёт о работе','Зафиксируйте схему портов, симптом, исходные настройки, действия по порядку, наблюдения до и после, локализованную причину, конечную проверку и возвращённую конфигурацию. Для разбора без оборудования укажите «анализ учебного случая».',
'Критерий выполнения — воспроизводимая локализация и подтверждённая конечная функция в пределах доступного стенда. Различайте проверенную заменой линию и предположение о её повреждении. Если оборудование недоступно, можно сдать анализ двух случаев, но он не подтверждает практическую настройку реального дисплея.')],
dict(prompt='Кабель подключён к IN 1, выбран IN 2. Какое изменение проверить первым?',options=['Переустановить ОС','Выбрать IN 1','Заменить все устройства','Отключить защиту сети'],correct=1,explanation='Наблюдение непосредственно указывает на несоответствие выбранного входа порту кабеля.'),
dict(task='Назовите локализованную причину: «вход» или «кабель».',output='Введите одно слово.',variants=[
V('Выбор входа','Кабель в IN 1; выбран IN 2; после выбора IN 1 изображение появилось.',[('Порты','Кабель IN 1'),('Выбор','IN 2'),('Изменение одного фактора','IN 1 → изображение')],'Вход','Не совпадал выбранный вход. Итог подтверждён появлением тестовой картинки по тому же тракту.',['вход']),
V('Замена кабеля','Вход и режим верны. Исходный кабель не работает; проверенный короткий работает при том же источнике и дисплее.',[('Условия','Источник, вход, режим неизменны'),('Исходный','Нет картинки'),('Проверенный','Картинка есть')],'Кабель','Замена одного фактора локализует исходный кабельный тракт. Проверить соединение и допустимость длины перед окончательной заменой.',['кабель'])]),'video')

lab('lab-cctv',5,4,'Обслуживание системы видеонаблюдения',
'Как подтвердить запись и воспроизведение, а не только живое видео?',
'Стенд: учебная камера, изолированная сеть, регистратор с выделенным накопителем и рабочее место. Используйте тестовую сцену без персональных данных; настройки интерфейса берите из руководства модели.',[
C('Исходные условия','Схема: камера → PoE-коммутатор → регистратор → рабочее место. Заданы разрешённые адреса, учётная запись оператора и политика хранения. Учебный тест: запись 3 минут с заметным событием на второй минуте.',
'Перед изменением сохраните текущие настройки предусмотренным способом. Проверьте совместимость питания, адреса, полномочия и свободное место. Живое видео используется для проверки тракта и времени камеры. Не форматируйте существующий накопитель ради запуска работы; выделенное учебное хранилище подготавливается по порядку преподавателя.'),
C('Настройка записи','Проверьте время камеры и регистратора; выберите учебный канал, разрешённый профиль потока и непрерывную запись на время теста; убедитесь в состоянии накопителя и активном расписании. Создайте событие, отметьте время, завершите интервал.',
'У разных моделей названия пунктов отличаются, поэтому отчёт включает реальные названия и снимки. Для первого опыта непрерывная запись отделяет проверку хранения от настройки детектора движения. Если задание использует запись по событию, отдельно проверяют событие и предзапись. Значок «камера онлайн» не доказывает активность расписания и запись на диск.'),
C('Проверка архива и неисправности','Откройте воспроизведение за известный интервал; найдите событие на второй минуте; проверьте начало, конец и отметки времени. Если видео онлайн есть, а архива нет, проверьте канал записи, расписание, накопитель, полномочия и время поиска.',
'При поиске по неверному времени исправная запись выглядит отсутствующей. Сопоставьте время теста с часами регистратора. Если накопитель недоступен, не делайте вывод о неисправности камеры. Экспорт короткого фрагмента выполняется только в предусмотренное место и по разрешённым правам. После работы верните согласованный режим записи.'),
C('Отчёт о работе','Сдайте схему, параметры теста, временные отметки, доказательство живого потока и отдельное доказательство воспроизведения архива, найденное отклонение и повторную проверку. Укажите, где выполнялся реальный тест, а где только анализ.',
'Полезное доказательство записи содержит узнаваемое учебное событие и диапазон времени. Снимок пустого календаря не позволяет отличить отсутствие записи от неправильного фильтра. Для теоретического варианта преподаватель выдаёт набор наблюдений; анализ такого набора не называют настройкой действующего регистратора.')],
dict(prompt='Живой поток есть, архив ищут на час раньше тестового события. Что проверить прежде вывода об отказе записи?',options=['Время камеры, регистратора и интервал поиска','Заменить камеру','Очистить диск','Сразу удалить расписание'],correct=0,explanation='Несогласованное время способно скрыть существующий фрагмент в другом интервале. Хранилище не очищают для диагностики.'),
dict(task='Какой участок непосредственно указан наблюдениями: «расписание» или «время»?',output='Введите одно слово.',variants=[
V('Канал не записывается','Онлайн-видео есть; время верно; накопитель исправен; запись для канала в расписании выключена.',[('Поток','Есть'),('Время и диск','Проверены'),('Расписание','Запись выключена')],'Расписание','Нужно разрешённо включить запись учебного канала и проверить новый фрагмент. Это не восстановит прошлый незаписанный интервал.',['расписание']),
V('Иной час','Запись активна и фрагмент существует; регистратор показывает 15:00 при эталонном 14:00; поиск выполняли только около 14:00.',[('Запись','Фрагмент есть'),('Часы','Сдвиг +1 ч'),('Поиск','Выбран неверный интервал')],'Время','Проверить источник времени и часовой пояс по руководству, найти существующий фрагмент с учётом сдвига; изменение часов согласуют.',['время'])]),'video')

lab('lab-lan',5,5,'Обслуживание локальной сети информационной системы',
'Как локализовать неисправность по наблюдениям разных уровней?',
'Используйте изолированный Windows-стенд: клиент 192.168.50.10/24, сервер 192.168.50.20/24, имя ufis-server, учебный TCP-сервис 8080. Адреса допустимы только в этом стенде.',[
C('Подготовка и фиксация','Нарисуйте клиент → коммутатор → сервер. Запишите IP, маску, шлюз, DNS и источник адреса. В PowerShell: ipconfig /all; Get-NetAdapter. Сначала наблюдайте, не меняйте все параметры одновременно.',
'Шлюз для связи двух узлов в одном сегменте не является обязательным маршрутом. Имя должно разрешаться предусмотренным в стенде способом. Перед проверкой преподаватель запускает учебный TCP-сервис на 8080; отсутствие подготовленного сервиса нельзя выдавать за доказанный сетевой дефект. Не используйте эти адреса для сканирования чужой сети.'),
C('Проверка связности и имени','Выполните ping 192.168.50.20; Resolve-DnsName ufis-server; Test-NetConnection 192.168.50.20 -Port 8080; затем ту же проверку по имени. Запишите фактические ответы и условие разрешения ICMP.',
'При запрещённом ICMP отрицательный ping не завершает диагностику. TCP-проверка относится к подготовленному порту, а не к произвольному стандартному номеру. Если адрес работает, а имя возвращает другое значение, проверяем разрешение имени. Если оба указывают верно, но сервис остановлен, проверяем приложение. Команды здесь читают состояние и не исправляют его автоматически.'),
C('Два типовых отклонения','A: у клиента ошибочный префикс /32 вместо /24 и нет маршрута к серверу; исправление по согласованным параметрам восстанавливает путь. B: IP и TCP работают, но имя указывает на .21 вместо .20.',
'Для A проверяется конфигурация адреса и маршрут: нельзя объявлять любую маску единственной причиной без наблюдений. Для B локализуется разрешение имени. Исправления выполняют только в учебном стенде и фиксируют одно изменение за раз. После каждого изменения повторяют исходную проверку, а в конце открывают подготовленный сервис и выполняют его контрольную операцию.'),
C('Отчёт и завершение','Сдайте схему, таблицу параметров, команды с результатами, гипотезу, одно подтверждающее сравнение, исправление и конечную проверку. Верните конфигурацию стенда в заданное состояние.',
'Успех конечного TCP-теста ещё не доказывает правильность данных приложения, поэтому отдельно укажите выполненную прикладную операцию. Если реального сервиса нет, обозначьте, что подтверждён только сетевой уровень. Сохраняйте ограничения вывода: неуспешный тест может быть следствием разрешённой фильтрации, а успешный — не распространяется на другие порты.')],
dict(prompt='Какой тест проверяет TCP-доступ к подготовленному порту 8080 в Windows?',options=['Test-NetConnection 192.168.50.20 -Port 8080','ipconfig /release на всех компьютерах','Удаление сетевого адаптера','Переименование сервера'],correct=0,explanation='Test-NetConnection с -Port проверяет установление TCP-соединения к указанному порту; остальные действия не являются этой проверкой.'),
dict(task='Выберите ближайшую проверку: «имя» или «сервис».',output='Введите одно слово.',variants=[
V('Расхождение адреса','TCP к .20:8080 проходит; ufis-server разрешается в .21.',[('Адрес','Порт доступен'),('Имя','.21 вместо .20'),('Локализация','Источник разрешения имени')],'Имя','Сначала проверить DNS или другой предусмотренный источник имени, затем повторить по имени и выполнить операцию.',['имя']),
V('Приложение остановлено','Имя правильно даёт .20, сеть доступна, процесс учебного сервиса остановлен; 8080 не слушается.',[('Имя','Правильно'),('Сеть','Доступна'),('Процесс','Остановлен')],'Сервис','По условиям требуется восстановить учебный сервис, затем повторить TCP и прикладную проверку.',['сервис'])]),'network')

lab('lab-expansion',5,6,'Разработка предложений о расширении информационной системы',
'Какие ограничения проверяют до закупки новых рабочих мест?',
'Результат — предложение с расчётом портов и нагрузки, изменениями состава, схемы и документов, планом ввода и отката. Числа условные и относятся к заданной конфигурации.',[
C('Исходные данные','Коммутатор: 24 порта, занято 20. План: +6 АРМ и +2 сетевых принтера. Сервис проверен до 30 одновременных сеансов; сейчас 22; новые АРМ создают ещё 6. Устройства не требуют PoE.',
'Сначала считаем разные ресурсы отдельно: порты, одновременные сеансы, питание и лицензии. Принтер требует сетевой порт, но в этой модели не создаёт пользовательский сеанс. Возможности сервиса заданы как проверенный предел для конкретного профиля, а не универсальная паспортная цифра. Лицензии и розетки в исходных данных не подтверждены — они остаются пунктами проверки.'),
C('Расчёт и варианты','Свободно 4 порта; требуется 8 — дефицит 4 порта без учёта новых межкоммутаторных соединений. После расширения 28 сеансов ≤ 30. Варианты: заменить коммутатор или добавить второй, учитывая uplink на обоих устройствах.',
'Дефицит четырёх — промежуточный результат, а не готовая спецификация закупки. При добавлении коммутатора uplink займёт один порт существующего устройства и один нового. Поэтому на старом останется три свободных порта для конечных устройств, а новый должен обеспечить ещё пять конечных подключений плюс uplink. Также проверяют пропускную способность uplink, VLAN, питание и сопровождение.'),
C('Предложение и план ввода','Обоснуйте вариант по обязательным ограничениям; укажите состав, связи, лицензии, питание и копию конфигурации. Ввод: подготовка → подключение одного АРМ → контроль операции → остальные устройства → проверка нагрузки. Откат возвращает исходную схему.',
'Критерии приёмки должны измеряться: все восемь новых сетевых устройств подключены, 28 сеансов проходят заданный профиль, данные сохраняются, старые рабочие места доступны. Если параметр неизвестен, предложите проверку, а не молчаливое допущение. План обслуживания добавленного оборудования входит в эксплуатационный результат.'),
C('Отчёт','Сдайте исходную и целевую схемы, расчёты, таблицу неизвестных условий, выбранный вариант, порядок ввода, критерии проверки и откат. Официальные часы и финансовую смету не придумывайте.',
'Оценка пригодности зависит от предоставленных ограничений. В работе достаточно условных ресурсов и явно отмеченных неизвестных данных; реальные цены нужны только при отдельном задании. Другой специалист должен суметь проверить, откуда получено каждое число и почему выбранная конфигурация сохраняет работу существующих пользователей.')],
dict(prompt='При добавлении второго коммутатора что нужно учесть сверх портов новых устройств?',options=['Только цвет корпуса','Uplink на обоих устройствах и его пропускную способность','Ничего','Автоматическое удвоение производительности сервера'],correct=1,explanation='Межкоммутаторная связь использует порты и общий канал; она не создаёт вычислительную мощность сервера.'),
dict(task='Сколько свободных портов существующего коммутатора останется после выделения одного uplink?',output='Введите число; начальная занятость дана в каждом случае.',variants=[
V('20 заняты','24 порта, 20 заняты; один свободный выделяется под uplink.',[('Свободно до','24 − 20 = 4'),('Uplink','Минус 1'),('Для конечных узлов','3')],'3','На существующем устройстве остаётся 3 свободных порта. Порт uplink нового коммутатора учитывается отдельно.',['3']),
V('22 заняты','24 порта, 22 заняты; один свободный выделяется под uplink.',[('Свободно до','24 − 22 = 2'),('Uplink','Минус 1'),('Для конечных узлов','1')],'1','После uplink остаётся один порт для конечного устройства; первоначальный ответ 3 к новому состоянию не подходит.',['1'])]),'architecture')

lab('lab-passport',5,7,'Составление паспорта информационной системы',
'Как связать паспорт с фактическим составом и инструкцией?',
'Составьте паспорт учебной складской ИС. Используйте данные работы № 1 и дополнения ниже. Недостающие сведения отметьте как требующие проверки, без вымышленных серийных номеров и паролей.',[
C('Данные паспорта','Назначение: приёмка и отпуск. SRV-01 — сервис и СУБД; SW-01 — коммутатор; BAK-01 — отдельное хранилище копий; 11 АРМ. Ответственный — роль администратора. Параметры копирования и восстановления пока не проверены.',
'Паспорт должен отличать предоставленный факт от отсутствующего сведения. Указание «копия есть» не даёт ни расписания, ни срока хранения, ни доказательства восстановления. Эти поля остаются «требует проверки» с планом получения данных. Роль администратора не заменяют выдуманным именем человека. Адреса и номера оборудования добавляют только из учебного задания или фактической разрешённой проверки.'),
C('Структура паспорта','Заполните назначение и границы; таблицу состава с ID; размещение и связи; зависимости; роли и доступ; обслуживание; копирование и восстановление; ссылки на схемы и инструкции; перечень неизвестных сведений.',
'Шаблон доступен по ссылке «Паспорт системы» в материалах лабораторной. Каждая строка состава должна иметь связь со схемой. Секреты в шаблон не включаются: вместо значения указывают защищённый порядок получения. Для неизвестного параметра полезно написать, кто и каким действием сможет его проверить. Паспорт остаётся кратким входом в комплект, а подробные операции выносятся в инструкцию.'),
C('Контрольная инструкция','Составьте инструкцию проверки сервиса: исходный доступ и предел действий; обращение по предусмотренному адресу; контрольная приёмка учебного товара; проверка документа и остатка; возврат учебных данных; остановка при расхождении.',
'Инструкция должна содержать ожидаемый результат каждого шага. Если нет подтверждения сохранения, не переходите к очистке исходных данных. Откат учебной операции выполняется по предусмотренному механизму, а не удалением случайных строк базы. Если реальный стенд не предоставлен, опишите проверку как план и не приписывайте ей выполненный результат.'),
C('Проверка и сдача','Другой участник по паспорту находит SRV-01 и BAK-01 на схеме, определяет роль и список зависимостей, объясняет проверку приёмки. Сдайте паспорт, схему, инструкцию и перечень вопросов, оставшихся без данных.',
'Главный критерий — согласованность комплекта. Адреса, идентификаторы и роли совпадают во всех документах. Неизвестное не превращается в установленный факт. Выполненное восстановление отмечают только при наличии реального результата; заполненная строка «восстановление» сама этого не подтверждает.')],
dict(prompt='Что записать в поле времени восстановления, если оно не измерялось?',options=['1 минута для красоты','Требует проверки; описать план измерения','0, потому что отказов не было','Бесконечная готовность'],correct=1,explanation='Отсутствующее измерение не заменяют выдуманным числом. Указывают пробел и способ его закрыть.'),
dict(task='Сколько строк состава требуют уточнения, если неизвестность считается по объектам?',output='Введите число; несколько неизвестных параметров одного объекта дают одну строку.',variants=[
V('Два объекта','У SRV-01 не проверен адрес; у BAK-01 не проверены расписание и восстановление; SW-01 проверен.',[('SRV-01','Одна строка'),('BAK-01','Одна строка, два параметра'),('Всего','2 строки')],'2','Счёт по объектам: SRV-01 и BAK-01. Три неизвестных параметра не означают три строки.',['2']),
V('Один объект уточнён','Адрес SRV-01 проверен; у BAK-01 всё ещё неизвестны расписание и восстановление; SW-01 проверен.',[('SRV-01','Уточнён'),('BAK-01','Одна строка остаётся'),('Всего','1 строка')],'1','Остаётся BAK-01. Два неизвестных поля этого объекта входят в одну строку состава.',['1'])]),'systems')

lab('lab-single',6,1,'Расчёт единичных показателей надёжности',
'Как из журнала получить три разных показателя?',
'Рассчитайте наработку на отказ, среднее восстановление и вероятность безотказной работы по явно принятой модели. Сохраните исходные данные и единицы.',[
C('Исходные данные','Суммарная рабочая наработка 2400 ч; 8 отказов; завершённые восстановления: 1, 2, 3, 2, 1, 4, 2, 1 ч. Отдельная выборка: из 50 объектов 46 прошли 24 ч без отказа; наблюдение полное.',
'Это две разные выборки. Первая относится к восстанавливаемым объектам и длительностям, вторая — к доле объектов, прошедших фиксированный горизонт. Их нельзя складывать. Сначала подсчитайте сумму восстановлений, затем проверьте количество элементов. Для модели в этой работе принимается постоянная интенсивность λ=1/T̄; её применимость к реальной системе здесь не исследуется.'),
C('Задание и порядок','Найдите T̄, T̄в и эмпирическую R̂(24 ч). Затем при λ=1/T̄ рассчитайте модельную R(24 ч). Округлите средние до 3 знаков, вероятности до 4. Объясните, почему две оценки R не обязаны совпасть.',
'Работайте самостоятельно до открытия разбора. Наработка уже исключает простой; повторно вычитать восстановления нельзя. Для вероятности по выборке используйте 46/50. В экспоненте берите 24 часа и интенсивность в обратных часах. Различие результатов связано с разными данными и предпосылкой модели; оно не является автоматически арифметической ошибкой.'),
C('Состав отчёта','Таблица данных; определения показателей; формулы с подстановкой; размерности; результаты и округление; интерпретация; пределы вывода; отдельный ответ, что делать при нуле зарегистрированных отказов.',
'Эталон после попытки: T̄=300 ч; сумма восстановлений 16 ч, среднее 2 ч; R̂=0,92; λ=1/300 ч⁻¹; модельная R(24)=exp(−0,08)≈0,9231. При нуле отказов простое отношение 2400/0 не даёт конечной оценки и не доказывает бесконечную надёжность. Для обоснованной оценки потребовались бы иной метод и указание неопределённости.')],
dict(prompt='Какова сумма восьми заданных восстановлений?',options=['8 ч','16 ч','24 ч','2400 ч'],correct=1,explanation='1+2+3+2+1+4+2+1=16 ч; среднее 16/8=2 ч.'),
dict(task='Рассчитайте среднее восстановление по завершённым случаям.',output='Введите часы без единицы.',variants=[
V('Восемь случаев','1, 2, 3, 2, 1, 4, 2, 1 ч.',[('Сумма','16 ч'),('Количество','8'),('Среднее','2 ч')],'2','16/8=2 ч. Все случаи завершены и учитываются одинаково.',['2']),
V('Четыре случая','1, 3, 4, 4 ч.',[('Сумма','12 ч'),('Количество','4'),('Среднее','3 ч')],'3','12/4=3 ч. Не переносите количество отказов из другого набора.',['3'])]),'reliability')

lab('lab-availability',6,2,'Расчёт комплексных показателей надёжности',
'Как согласовать коэффициент готовности с фондом времени?',
'Постройте таблицу неперекрывающихся состояний и рассчитайте показатели. Плановое обслуживание в этой работе учитывается отдельно от восстановления.',[
C('Исходные данные','Модель: T̄=120 ч, T̄в=3 ч. Журнал другого учебного периода: работа 840 ч, восстановление 35 ч, обслуживание 125 ч. Все интервалы журнала неперекрывающиеся; иных состояний нет.',
'Модельные средние и конечный журнал — два набора. Формула стационарной готовности использует 120 и 3, а эмпирические доли журнала — 840, 35 и 125. Не нужно искусственно приводить число отказов журнала к 120 часам: таких данных не дано. Явная маркировка набора предотвращает смешение знаменателей.'),
C('Задание','Вычислите модельный Kг; по журналу долю работы в фонде «работа + восстановление» и Kти полного фонда. Для каждого числа укажите вопрос и знаменатель. Вероятности округлите до 4 знаков.',
'Сначала выпишите выражения без вычисления. Модельный Kг=120/(120+3). Узкая доля журнала=840/(840+35). Полный фонд=1000. Затем посчитайте, объясните различия и проверьте, что все доли находятся между нулём и единицей. Плановое обслуживание не является числом отказов.'),
C('Проверка и отчёт','Сдайте таблицу фонда, формулы, результаты, различие модели и наблюдения. Дополнительно рассчитайте Kти при сокращении обслуживания до 75 ч и увеличении работы до 890 ч при прежнем восстановлении 35 ч.',
'Эталон после попытки: Kг модели≈0,9756; доля журнала 840/875=0,96; Kти=0,84. Изменённый полный фонд остаётся 1000 ч; Kти=0,89. Изменение составляет 5 процентных пунктов. Это не даёт права назвать 0,89 договорной доступностью: договорный показатель в исходных данных не задан.')],
dict(prompt='Каков полный фонд исходного журнала?',options=['875 ч','965 ч','1000 ч','840 ч'],correct=2,explanation='840+35+125=1000 ч; каждое неперекрывающееся состояние включается один раз.'),
dict(task='Рассчитайте Kти по полному фонду.',output='Введите долю.',variants=[
V('Исходный фонд','Работа 840 ч, восстановление 35 ч, обслуживание 125 ч.',[('Фонд','1000 ч'),('Числитель','840 ч'),('Доля','0,84')],'0,84','840/1000=0,84. Включены оба вида простоя.',['0,84','0.84']),
V('Обслуживание сокращено','Работа 890 ч, восстановление 35 ч, обслуживание 75 ч.',[('Фонд','1000 ч'),('Числитель','890 ч'),('Доля','0,89')],'0,89','890/1000=0,89. Работа выросла на освободившиеся 50 ч по условию.',['0,89','0.89'])]),'reliability')

lab('lab-redundancy',6,3,'Расчёт надёжности системы и эффекта резервирования',
'Как пересчитать систему после резервирования одного звена?',
'Постройте логическую схему функции, выделите резервную группу и общий компонент. Все вероятности относятся к одному заданному горизонту.',[
C('Исходные данные','Обязательный сервер Rс=0,97; один канал Rк=0,92. Вариант резерва: два независимых канала по 0,92 с идеальным переключением и достаточной ёмкостью каждого. Сервер независим от каналов.',
'Первая схема содержит два обязательных звена. Во второй сеть становится параллельной группой, но сервер остаётся обязательным. Условия идеального переключения заданы для учебной формулы и не считаются свойством любой реальной системы. Отдельный третий вариант добавит общий коммутатор; его учитывают как самостоятельную зависимость.'),
C('Задание','Рассчитайте исходную надёжность; надёжность резервной группы; итог с сервером; абсолютное улучшение и процентные пункты. Затем добавьте общий коммутатор R=0,96, независимый от остальных объектов.',
'Порядок: 0,97×0,92; затем 1−0,08²; затем умножение на сервер; для третьего варианта ещё на 0,96. Не умножайте два независимых успешных канала для модели «хотя бы один»: произведение успехов требовало бы оба. Покажите проверку результата по пределам обязательных элементов.'),
C('Отчёт и эталон после попытки','Сдайте три схемы, формулы, расчёты до 6 знаков, допущения и план проверки переключения. Исходно 0,8924; резервная сеть 0,9936; система 0,963792; с общим коммутатором 0,92524032.',
'Эффект резерва относительно исходного варианта: 0,071392, или 7,1392 процентного пункта. Общий коммутатор снижает результат относительно варианта без этой зависимости. Полученные значения не следует превращать в годовой простой: вероятность безотказной работы на горизонте и календарная готовность различны. Практическое испытание должно подтвердить именно продолжение функции на оставшемся канале.')],
dict(prompt='Почему общий коммутатор учитывается последовательно?',options=['Он обязателен при работе любого канала','Потому что кабели прямые','Потому что все вероятности меньше 1','Он не влияет'],correct=0,explanation='При его отказе оба пути теряют функцию; условие успеха требует и резервную группу, и общий коммутатор.'),
dict(task='Рассчитайте надёжность только резервной группы из двух одинаковых независимых каналов.',output='Введите долю; сервер здесь не включайте.',variants=[
V('Каналы 0,92','Два канала по R=0,92, достаточно любого, переключение идеально.',[('Отказ одного','0,08'),('Совместный отказ','0,0064'),('Успех группы','0,9936')],'0,9936','1−(1−0,92)²=0,9936. Это ещё не итог системы с сервером.',['0,9936','0.9936']),
V('Каналы 0,95','Два канала по R=0,95, остальные условия те же.',[('Отказ одного','0,05'),('Совместный отказ','0,0025'),('Успех группы','0,9975')],'0,9975','1−0,05²=0,9975. Увеличение надёжности каналов повысило показатель группы.',['0,9975','0.9975'])]),'reliability')

lab('lab-integrity',6,4,'Определение показателей достоверности информации',
'Как посчитать ошибки, не смешивая записи и поля?',
'Проверьте учебные записи по предоставленному эталону. Итог — журнал расхождений, доли по записям и полям, выбор контролей и план повторной проверки.',[
C('Набор для сверки','Четыре записи, два поля: код и количество. Эталон: A01=10; A02=20; A03=30; A04=40. Получено: A01=10; A02=200; A3=30; A04=40. Строки сопоставляются по заданной позиции, чтобы ошибка кода не потеряла запись.',
'Все восемь полей подлежат сравнению. Вторая строка содержит ошибку количества, третья — ошибку кода. Учебное правило позиционного сопоставления необходимо: если искать только по совпавшему коду, строка A3 может исчезнуть из знаменателя. В реальной сверке используют устойчивый идентификатор или явную процедуру сопоставления.'),
C('Задание','Выпишите каждое расхождение с номером строки, полем, эталоном и фактом. Найдите число ошибочных записей, число неверных полей, q и D для каждого основания. Предложите контроль кода, диапазона и независимую сверку.',
'Работайте до открытия решения. Поле с верным количеством и неверным кодом не становится целиком правильной записью. Формат кода в этом наборе задан как буква A и две цифры; A3 не проходит. Для количества заранее заданный диапазон 0–100 обнаружит 200, но пропустил бы ошибочные 21 вместо 20. Это демонстрирует предел диапазонного контроля.'),
C('Отчёт и проверка после попытки','Ошибочны 2 записи из 4: qзап=0,5, Dзап=0,5. Неверны 2 поля из 8: qполей=0,25, Dполей=0,75. После разрешённого исправления повторите сверку и проверьте, что обе причины отражены в журнале.',
'Значения D различаются, потому что знаменатели относятся к разным единицам учёта. Исправление кода и количества должно вернуть точное соответствие учебному эталону, но не превращает метод в доказательство достоверности любых производственных данных. В выводе указывайте, что проверен конкретный полный набор.')],
dict(prompt='Сколько записей ошибочно в исходном наборе?',options=['1','2','4','8'],correct=1,explanation='Вторая строка имеет неверное количество, третья — неверный код. Это две ошибочные записи.'),
dict(task='Рассчитайте D по полям в указанном наборе из 8 проверенных полей.',output='Введите долю.',variants=[
V('Две ошибки','Неверны 2 из 8 полей.',[('qполей','2 / 8 = 0,25'),('Dполей','1 − 0,25'),('Результат','0,75')],'0,75','Доля правильных полей 6/8=0,75. Не используйте число записей в знаменателе.',['0,75','0.75']),
V('Одна ошибка исправлена','После исправления кода осталось 1 неверное поле из 8.',[('qполей','1 / 8 = 0,125'),('Dполей','1 − 0,125'),('Результат','0,875')],'0,875','Правильны 7/8 полей. Нужно исправить оставшееся расхождение и повторить сверку.',['0,875','0.875'])]),'integrity')

lab('lab-performance',6,5,'Измерение производительности и выявление узкого места',
'Как воспроизвести сравнение и проверить гипотезу ограничения?',
'Используйте разрешённый стенд либо приложенный учебный набор наблюдений. Анализ готовых чисел не заменяет самостоятельное измерение; в отчёте обозначьте выбранный режим.',[
C('Наблюдения двух прогонов','Одинаковые операция, данные, 20 клиентов и интервал 60 с. A: 600 завершений, 0 ошибок; задержки выборки: 120,120,130,130,140,150,160,180,300,900 мс. B: 900 завершений, 0 ошибок; 100,100,110,110,120,120,130,140,160,300 мс.',
'В каждом прогоне выборка задержек содержит десять наблюдений и не является полным журналом всех завершений. Для учебного p95 используйте ближайший ранг. Пропускную способность считайте по всем завершениям за интервал. Условия заявлены одинаковыми; в реальном измерении это требуется зафиксировать, включая кэш и фоновую активность.'),
C('Ресурсы и гипотеза','A: CPU 35%, ожидание запросов на диске растёт; средняя задержка диска 45 мс. B после одного изменения хранения: CPU 45%, задержка диска 8 мс. Данные являются признаками, а не окончательным доказательством единственной причины.',
'Сформулируйте гипотезу о хранении как ограничении. Для проверки на стенде собирают очередь и время дисковых операций одновременно с пользовательскими задержками. Сопоставимое улучшение после одного изменения поддерживает гипотезу, но на малом наборе не исключает альтернативы. Добавлять CPU только из-за наличия слова «производительность» не обосновано.'),
C('Порядок выполнения','Задайте сценарий и границы измерения; сохраните конфигурацию; выполните подготовку и прогон; соберите завершения, ошибки, задержки и ресурсы; измените один фактор по разрешению; повторите профиль и контроль данных.',
'Если стенд отсутствует, выполните расчёт по двум наборам и предложите процедуру будущего измерения. Не направляйте запросы на публичный сайт для имитации лабораторной нагрузки. Для реального стенда приложите используемую команду или сценарий инструмента, его настройки и фактические результаты. Изменение оборудования без сопоставимого повторения не подтверждает эффект.'),
C('Что сдавать','Таблица условий; исходные наблюдения; X, среднее и p95; ошибки; гипотеза узкого места; подтверждающие и недостающие данные; изменение; вывод о пределах результата. Отдельно подтвердите корректность контрольной операции.',
'Эталон вычислений после попытки: A — X=10 оп/с, среднее 233 мс, p95=900 мс; B — X=15 оп/с, среднее 139 мс, p95=300 мс. X выросла на 50 процентов; p95 снизился на 600 мс. Выборка из десяти задержек ограничивает точность вывода о хвосте распределения; это следует написать, а не скрыть округлением.')],
dict(prompt='Какой вывод лучше поддержан наблюдениями A?',options=['Нужно обязательно удвоить CPU','Хранение — гипотеза ограничения, которую проверяют по очереди и сопоставимому изменению','Все пользователи получают ответ за среднее','Производительность равна частоте процессора'],correct=1,explanation='Невысокий CPU и рост дисковых ожиданий поддерживают гипотезу о хранении. Для вывода нужны связанные измерения и контроль условий.'),
dict(task='Рассчитайте пропускную способность по всем завершениям за 60 с.',output='Введите операций/с без единицы.',variants=[
V('Прогон A','600 завершений за 60 с, ошибок 0.',[('Завершения','600'),('Интервал','60 с'),('X','600 / 60 = 10 оп/с')],'10','Считаем завершения, а не число клиентов или выборочных задержек.',['10']),
V('Прогон B','900 завершений за 60 с, ошибок 0.',[('Завершения','900'),('Интервал','60 с'),('X','900 / 60 = 15 оп/с')],'15','900/60=15 оп/с. Для сравнения сохраняем тот же профиль и границы измерения.',['15'])]),'performance')
